//! Bit-exact parity with Go's internal/nodeshape (fixture generated by
//! goref/d2/d2layouts/d2talalayout/cmd/nodeshaperef via `scripts/gen-goref.sh`;
//! shipped as tests/fixtures/go-unit/nodeshape.txt).
#![allow(non_snake_case)]
extern crate orthoflow_nodeshape as nodeshape;
use nodeshape::*;

fn h(f: f64) -> String {
    format!("{:016x}", f.to_bits())
}
fn ints(v: &[i64]) -> String {
    format!("[{}]", v.iter().map(|x| x.to_string()).collect::<Vec<_>>().join(","))
}
fn q(s: &str) -> String {
    format!("\"{}\"", s)
}

const TYPES: &[&str] = &[
    "Square", "RealSquare", "Parallelogram", "Document", "Cylinder", "Queue", "Page", "Package", "Step", "Callout", "StoredData", "Person",
    "C4Person", "Diamond", "Oval", "Circle", "Hexagon", "Cloud", "Table", "Class", "Text", "Code", "Image", "", "weird",
];
const BOXES: &[[f64; 4]] = &[
    [0.0, 0.0, 100.0, 100.0],
    [10.0, 20.0, 200.0, 80.0],
    [-50.5, 33.25, 40.0, 30.0],
    [7.0, 9.0, 25.0, 300.0],
    [100.0, 100.0, 150.0, 61.0],
    [3.3, 4.4, 59.0, 47.0],
    [0.0, 0.0, 1.0, 1.0],
    [12.0, 34.0, 834.0, 523.0],
    [5.0, 5.0, 333.3, 111.1],
    [-200.0, -100.0, 61.044, 20.0],
    [1.0, 2.0, 13.0, 17.0],
    [0.0, 0.0, 99.0, 67.0],
];

#[test]
fn nodeshape_parity() {
    let orients = [geo::TopLeft, geo::TopRight, geo::BottomLeft, geo::BottomRight, geo::Top, geo::Right, geo::Bottom, geo::Left, geo::NONE];
    let dir = std::fs::canonicalize(env!("CARGO_MANIFEST_DIR")).unwrap();
    let want = std::fs::read_to_string(dir.join("../../tests/fixtures/go-unit/nodeshape.txt")).expect("fixture");
    let mut out: Vec<String> = Vec::new();
    for t in TYPES {
        for (bi, b) in BOXES.iter().enumerate() {
            for cols in 0..6i64 {
                if *t != "Table" && cols > 0 {
                    break;
                }
                let box_ = geo::NewBox(geo::NewPoint(b[0], b[1]), b[2], b[3]);
                let (s, kind, ok) = New(t, box_);
                out.push(format!("new {} {} {} {} {}", q(t), bi, cols, kind.0, ok));
                if !ok {
                    continue;
                }
                let s = s.unwrap();
                SetNumColumns(&*s, cols);
                out.push(format!("kind {} numcols {}", kind.String(), NumColumns(&*s)));
                for (gi, g) in s.SnapPointPercentages().iter().enumerate() {
                    let parts: Vec<String> = g
                        .iter()
                        .map(|p| {
                            let p = p.b();
                            format!("{},{}", h(p.XPercentage), h(p.YPercentage))
                        })
                        .collect();
                    out.push(format!("snap {} {}", gi, parts.join(";")));
                }
                for o in orients {
                    out.push(format!("ports {} {} {}", o.0, ints(&s.PortIndices(o)), s.CenterPortIndex(o)));
                }
                let m = s.MirroredPortIndices();
                let mut keys: Vec<i64> = m.keys().copied().collect();
                keys.sort();
                let mp: Vec<String> = keys.iter().map(|k| format!("{}:{}", k, m[k])).collect();
                out.push(format!("mirror {} center {}", mp.join(","), ints(&s.CenterPortIndices())));
                for tier in 0..=4 {
                    let mut ps: Vec<i64> = s.LabelPositionPreferences(LabelTier(tier)).iter().map(|p| p.0 as i64).collect();
                    ps.sort();
                    out.push(format!("lpp {} {}", tier, ints(&ps)));
                }
                if *t == "Table" {
                    for o in orients {
                        for ci in 0..cols.max(1) {
                            let (idx, ok) = TablePortIndex(&*s, o, ci);
                            let (pv, ok2) = TableColumnPortValue(&*s, o, ci);
                            out.push(format!("tableport {} {} {} {} {},{} {}", o.0, ci, idx, ok, h(pv.X), h(pv.Y), ok2));
                        }
                    }
                }
            }
        }
    }
    let want: Vec<&str> = want.lines().collect();
    assert_eq!(out.len(), want.len());
    let mut fails = 0;
    for (i, (g, w)) in out.iter().zip(want.iter()).enumerate() {
        if g != w {
            if fails < 10 {
                eprintln!("line {}:\n  want {}\n  got  {}", i + 1, w, g);
            }
            fails += 1;
        }
    }
    assert_eq!(fails, 0);
}
